changeSet.sql:
CREATE TABLE listing_conflicts ( id uuid PRIMARY KEY, tenant_id uuid, branch_id uuid, created_at timestamptz NOT NULL, created_by varchar(255), updated_at timestamptz, updated_by varchar(255), deleted boolean NOT NULL DEFAULT false,
conflict_type varchar(16) NOT NULL, left_entity_id uuid NOT NULL, right_entity_id uuid NOT NULL, left_tenant_id uuid NOT NULL, right_tenant_id uuid NOT NULL,
-- The estate both plots belong to, for a PLOT_OVERLAP; null -- for an ESTATE_OVERLAP, where the two entities ARE estates. -- Not in the slice spec's column list, but the tenant-facing -- route is GET /api/portal/estates/{id}/conflicts, which -- needs to find plot conflicts by their containing estate -- without joining back into inventory's tables. estate_id uuid,
overlap_area_sqm numeric(14,2) NOT NULL, left_overlap_pct numeric(5,2) NOT NULL, right_overlap_pct numeric(5,2) NOT NULL,
severity varchar(8) NOT NULL, status varchar(24) NOT NULL,
resolution_reason text, resolved_by_user_id uuid, resolved_at timestamptz, detected_at timestamptz NOT NULL,
-- Set by detection when a HIGH conflict's (or any confirmed -- duplicate's) overlap drops away, WITHOUT touching status. -- Deliberately does not by itself resolve the conflict or -- lift the publication block — see the long comment on -- changeset 047's detection functions for why: geometry no -- longer overlapping is not proof a genuine cross-company -- dispute was fixed rather than gamed (a boundary can be -- nudged just enough to duck the sliver threshold while -- keeping almost all of the disputed ground). This column -- is the signal a Super Admin uses to find conflicts that -- need a decision; only a human dismissing the conflict -- actually lifts the block. Null again if the geometry goes -- back to overlapping on a later re-scan. geometry_cleared_at timestamptz,
-- Deterministic pair ordering, enforced by the database -- rather than trusted of the service. Detecting A-vs-B and -- B-vs-A must produce one row, not two, and the unique index -- below can only do its job if the ordering is guaranteed. CONSTRAINT ck_listing_conflicts_pair_order CHECK (left_entity_id < right_entity_id),
-- No fabricated conflicts: a row exists only where geometry -- genuinely overlaps beyond the sliver threshold. CONSTRAINT ck_listing_conflicts_overlap_positive CHECK (overlap_area_sqm > 0),
CONSTRAINT ck_listing_conflicts_type CHECK (conflict_type IN ('ESTATE_OVERLAP', 'PLOT_OVERLAP')), CONSTRAINT ck_listing_conflicts_severity CHECK (severity IN ('HIGH', 'MEDIUM')), CONSTRAINT ck_listing_conflicts_status CHECK (status IN ('OPEN', 'INVESTIGATING', 'CONFIRMED_DUPLICATE', 'DISMISSED', 'AUTO_RESOLVED')) );
-- One live conflict per pair. CONFIRMED_DUPLICATE counts as live: -- a confirmed duplicate still blocks publication, so it is a -- standing consequence, not a closed case. DISMISSED and -- AUTO_RESOLVED are excluded so that geometry which is corrected -- and later broken again can raise a fresh conflict rather than -- colliding with the historical record, which is kept. CREATE UNIQUE INDEX uq_listing_conflicts_live_pair ON listing_conflicts (conflict_type, left_entity_id, right_entity_id) WHERE deleted = false AND status IN ('OPEN', 'INVESTIGATING', 'CONFIRMED_DUPLICATE');
CREATE INDEX idx_listing_conflicts_status ON listing_conflicts (status); CREATE INDEX idx_listing_conflicts_severity ON listing_conflicts (severity); CREATE INDEX idx_listing_conflicts_left_entity ON listing_conflicts (left_entity_id); CREATE INDEX idx_listing_conflicts_right_entity ON listing_conflicts (right_entity_id); CREATE INDEX idx_listing_conflicts_estate ON listing_conflicts (estate_id); CREATE INDEX idx_listing_conflicts_left_tenant ON listing_conflicts (left_tenant_id); CREATE INDEX idx_listing_conflicts_right_tenant ON listing_conflicts (right_tenant_id);
COMMENT ON TABLE listing_conflicts IS 'Detected geometric overlaps between two estates or two plots. Platform-owned: a conflict ' 'belongs to neither company, so tenant_id/branch_id stay null and RLS is platform-scope ' 'only. Tenant-facing reads go through landvault_tenant_estate_conflicts() instead, which ' 'never selects the counterparty''s identity. See AGENTS.md.'; COMMENT ON COLUMN listing_conflicts.overlap_area_sqm IS 'Square metres via ST_Area(ST_Intersection(a,b)::geography). Raw 4326 would give square ' 'degrees - a plausible-looking meaningless number.'; COMMENT ON COLUMN listing_conflicts.severity IS 'HIGH = the two entities belong to different tenants (two companies claim the same ground; ' 'a buyer could pay the wrong one). MEDIUM = same tenant, almost certainly a survey error.'; COMMENT ON COLUMN listing_conflicts.status IS 'AUTO_RESOLVED is set by detection only, never by a Super Admin - it means the geometry was ' 'corrected and the overlap no longer exists. The record is kept, never deleted.';
ALTER TABLE listing_conflicts ENABLE ROW LEVEL SECURITY; ALTER TABLE listing_conflicts FORCE ROW LEVEL SECURITY;
CREATE POLICY listing_conflicts_platform ON listing_conflicts FOR ALL USING (current_setting('landvault.platform_scope', true) = 'on') WITH CHECK (current_setting('landvault.platform_scope', true) = 'on');
